//! SCAR, the Star Citizen Area Reference, created by Murphy of the Murphy
//! Exploration Group. Ported from VerseGuide's `verseguide-scar.mjs`, verified
//! against golden values generated by that script.
//!
//! Its quirks are kept on purpose, since a code only means anything if it matches
//! everyone else's: the band table has 19 letters (no `V`), so 56-64° reads `W`
//! and 64-80° both read `X`, and the centre discriminator is the digit `0`.
//!
//! Latitude is north positive, longitude -180..180 east positive, in the frame
//! VerseGuide uses, which includes its per-body phase. Our own [`crate::Geo`]
//! has a different longitude zero until that phase is calibrated.

const BANDS: &[u8] = b"CDEFGHJKLMNPQRSTUWX";
const ALPHA24: &[u8] = b"ABCDEFGHJKLMNPQRSTUVWXYZ";

fn modulo(n: f64, m: f64) -> f64 {
    ((n % m) + m) % m
}

fn letter(table: &[u8], index: usize) -> char {
    table[index] as char
}

/// The full designation, e.g. `12T-NF47 / G`.
pub fn scar(lat: f64, lon: f64) -> String {
    format!(
        "{}{}-{}{}{}{} / {}",
        zone(lon),
        band(lat, lon),
        easting(lat, lon),
        northing(lat),
        quadrant(lat, lon),
        keypad(lat, lon),
        discriminator(lat, lon)
    )
}

/// SCAR from a position in the game's own body frame (any length unit).
pub fn scar_from_game_frame(v: crate::V3) -> String {
    let round8 = |x: f64| ((x + f64::EPSILON) * 1e8).round() / 1e8;
    let lat = -(v[0].hypot(v[1])).atan2(v[2]).to_degrees() + 90.0;
    let mut lon = -v[0].atan2(v[1]).to_degrees() - 90.0;
    if lon < 0.0 {
        lon += 360.0;
    }
    scar(round8(lat), round8(lon) - 180.0)
}

fn zone(lon: f64) -> String {
    let shifted = (if lon >= 180.0 { lon - 180.0 } else { lon }) + 180.0;
    format!("{:02}", (shifted / 6.0).floor() as i64 + 1)
}

fn band(lat: f64, lon: f64) -> char {
    if lat.abs() <= 80.0 {
        let idx = ((lat + 80.0) / 8.0).floor();
        letter(BANDS, idx.clamp(0.0, (BANDS.len() - 1) as f64) as usize)
    } else if lat > 0.0 {
        if lon < 0.0 { 'Y' } else { 'Z' }
    } else if lon < 0.0 {
        'A'
    } else {
        'B'
    }
}

fn easting(lat: f64, lon: f64) -> char {
    let x = if lat.abs() == 90.0 {
        1.0
    } else {
        (modulo(lon + 180.0, 360.0) / 0.5).floor() + 1.0
    };
    let mut pick = (x / 24.0 - (x / 24.0).floor()) * 24.0;
    if pick == 0.0 {
        pick = 24.0;
    }
    letter(ALPHA24, pick.round().clamp(1.0, 24.0) as usize - 1)
}

fn northing(lat: f64) -> char {
    let idx = if lat.abs() > 80.0 {
        let base = if lat > 0.0 { lat - 80.0 } else { lat + 90.0 };
        modulo((base / 0.5).floor(), 24.0)
    } else {
        modulo(((lat + 80.0) / 0.5).floor(), 16.0)
    };
    letter(ALPHA24, idx as usize)
}

fn quadrant(lat: f64, lon: f64) -> u8 {
    let lat_high = modulo((lat + 90.0) / 0.5, 1.0) >= 0.5;
    let lon_high = modulo(modulo(lon + 180.0, 360.0) / 0.5, 1.0) >= 0.5;
    match (lat_high, lon_high) {
        (true, false) => 1,
        (true, true) => 2,
        (false, false) => 3,
        (false, true) => 4,
    }
}

fn keypad_part(big: f64) -> i64 {
    let frac = big - big.floor();
    let fraction = if frac >= 0.5 { frac - 0.5 } else { frac };
    (6.0 * fraction).floor() as i64
}

fn keypad(lat: f64, lon: f64) -> u8 {
    let east = keypad_part(modulo(lon + 180.0, 360.0) / 0.5);
    let north = keypad_part((lat + 90.0) / 0.5);
    match (east, north) {
        (0, 2) => 1,
        (1, 2) => 2,
        (2, 2) => 3,
        (0, 1) => 4,
        (1, 1) => 5,
        (2, 1) => 6,
        (0, 0) => 7,
        (1, 0) => 8,
        (2, 0) => 9,
        _ => 0,
    }
}

fn discriminator(lat: f64, lon: f64) -> &'static str {
    let east = modulo((lon + 180.0) * 60.0, 5.0).floor() as i64;
    let north = modulo((lat + 90.0) * 60.0, 5.0).floor() as i64;
    const GRID: [[&str; 5]; 5] = [
        ["V", "W", "X", "Y", "Z"],
        ["Q", "R", "S", "T", "U"],
        ["L", "M", "0", "N", "P"],
        ["F", "G", "H", "J", "K"],
        ["A", "B", "C", "D", "E"],
    ];
    match (usize::try_from(north), usize::try_from(east)) {
        (Ok(n), Ok(e)) if n < 5 && e < 5 => GRID[n][e],
        _ => "",
    }
}

/// The centre of a SCAR's one-arcminute cell, `(lat, lon)` in degrees, by
/// searching the forward functions above (so every quirk inverts exactly).
/// Accepts `12T-NF47 / G`, `12tnf47g` and spacings between. `None` if no
/// cell has that code.
pub fn decode(code: &str) -> Option<(f64, f64)> {
    let c: Vec<char> = code
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .map(|c| c.to_ascii_uppercase())
        .collect();
    if c.len() != 8 {
        return None;
    }
    let zone_s: String = c[..2].iter().collect();
    let (band_c, east_c, north_c) = (c[2], c[3], c[4]);
    let quad = c[5].to_digit(10)? as u8;
    let key = c[6].to_digit(10)? as u8;
    let disc = c[7].to_string();
    // Half-degree cells first: zone, band, easting and northing.
    let mut cells = vec![];
    for i in 0..360 {
        let lat0 = -90.0 + i as f64 * 0.5;
        for j in 0..720 {
            let lon0 = -180.0 + j as f64 * 0.5;
            let (lat, lon) = (lat0 + 0.25, lon0 + 0.25);
            if band(lat, lon) == band_c
                && easting(lat, lon) == east_c
                && northing(lat) == north_c
                && zone(lon) == zone_s
            {
                cells.push((lat0, lon0));
            }
        }
    }
    // Then arcminutes within: quadrant, keypad, discriminator.
    let mut hits = vec![];
    for (lat0, lon0) in cells {
        for a in 0..30 {
            for b in 0..30 {
                let lat = lat0 + (a as f64 + 0.5) / 60.0;
                let lon = lon0 + (b as f64 + 0.5) / 60.0;
                if quadrant(lat, lon) == quad
                    && keypad(lat, lon) == key
                    && discriminator(lat, lon) == disc
                {
                    hits.push((lat, lon));
                }
            }
        }
    }
    match hits.as_slice() {
        [one] => Some(*one),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, scar, scar_from_game_frame};

    /// Every code decodes to a point inside its own cell, which encodes back
    /// to the same code.
    #[test]
    fn decode_round_trips() {
        for (lat, lon) in [
            (42.55, -113.73),
            (-15.66, 68.29),
            (0.01, 0.01),
            (-79.9, 179.9),
            (63.2, -0.4),
            (12.345, 101.234),
        ] {
            let code = scar(lat, lon);
            let (dlat, dlon) = decode(&code).unwrap_or_else(|| panic!("{code} did not decode"));
            assert_eq!(scar(dlat, dlon), code);
            assert!(
                (dlat - lat).abs() <= 1.0 / 60.0 && (dlon - lon).abs() <= 1.0 / 60.0,
                "{code}: {dlat} {dlon}"
            );
        }
        assert_eq!(
            decode("12tnf47g").map(|(a, b)| scar(a, b)),
            Some("12T-NF47 / G".into())
        );
        assert_eq!(decode("nonsense"), None);
    }

    #[test]
    fn documented_example() {
        assert_eq!(scar(42.55, -113.73), "12T-NF47 / G");
    }

    /// From the original script's `scarFromXYZ` on a real Zone reading.
    #[test]
    fn from_game_frame_matches_script() {
        assert_eq!(
            scar_from_game_frame([-64583.134917, -205899.879765, -60470.863496]),
            "13L-BA15 / V"
        );
    }

    /// `golden.txt`: `lat lon code`, generated by the original script.
    #[test]
    fn matches_original_script() {
        let golden = include_str!("scar_golden.txt");
        let mut n = 0;
        for line in golden.lines() {
            let (coords, want) = line.split_once('|').expect("lat lon|code");
            let (lat, lon) = coords.split_once(' ').expect("lat lon");
            let (lat, lon): (f64, f64) = (lat.parse().unwrap(), lon.parse().unwrap());
            assert_eq!(scar(lat, lon), want, "lat {lat} lon {lon}");
            n += 1;
        }
        assert!(n > 1000, "only {n} golden rows");
    }
}
